11: import type { TipoReserva } from "@/lib/recorrencia/types";
12: 
13: // ─── Tipos ────────────────────────────────────────────────────────────────────
14: 
15: export type StatusReserva =
16:   | "em_processamento" // lock temporário durante o checkout
17:   | "pendente"         // sinal pago, restante a pagar no dia
18:   | "confirmada"       // pagamento do sinal confirmado
19:   | "cancelada";       // reserva cancelada
20: 
21: export type StatusWhatsApp = "nao_enviado" | "enviado" | "falhou";
22: 
23: export interface Reserva {
24:   id: string;
25:   quadraId: string;
26: 
27:   // Identificação do cliente
28:   userId?: string;
29:   nomeCliente: string;
30:   whatsappCliente: string;
31:   cpfCliente: string;
32: 
33:   // Agendamento
34:   data: string;        // "YYYY-MM-DD"
35:   horarios: string[];  // ex: ["13:00", "14:00", "15:00"]
36:   horaInicio: string;  // primeiro slot
37:   horaFim: string;     // última hora + 1h (ex: "16:00")
38: 
39:   // Financeiro
40:   valorTotal: number;
41:   valorSinal: number;    // 40% do total
42:   valorPendente: number; // 60% do total
43: 
44:   // Estado
45:   status: StatusReserva;
46:   statusWhatsApp: StatusWhatsApp;
47:   criadaEm: string; // ISO datetime
48: 
49:   // Opcionais
50:   esporte?: Esporte;
51:   observacoes?: string;
52: 
53:   // Reservas recorrentes (escolinhas e grupos). Reservas avulsas deixam em branco.
54:   contratoId?: string;
55:   tipoReserva?: TipoReserva;
56:   /** Data (YYYY-MM-DD) em que o grupo avisou o cancelamento; null limpa o aviso no banco */
57:   avisoCancelamentoEm?: string | null;
58: }
59: 
60: // ─── State & Actions ──────────────────────────────────────────────────────────
61: 
62: interface ReservasState {
63:   reservas: Reserva[];
64:   isLoadedFromDb: boolean;
65: 
66:   // Mutations
67:   setReservas: (reservas: Reserva[]) => void;
68:   adicionarReserva: (reserva: Reserva) => void;
69:   atualizarReserva: (id: string, dados: Partial<Reserva>) => void;
70:   removerReserva: (id: string) => void;
71: 
72:   // Computed helpers (usados pelo service)
73:   getReservaById: (id: string) => Reserva | undefined;
74:   getReservasPorData: (data: string) => Reserva[];
75: }
76: 
77: // ─── Store ────────────────────────────────────────────────────────────────────
78: 
79: export const useReservasStore = create<ReservasState>()(
80:   persist(
81:     (set, get) => ({
82:       reservas: [],
83:       isLoadedFromDb: false,
84: 
85:       setReservas: (reservas) =>
86:         set({ reservas, isLoadedFromDb: true }),
87: 
88:       adicionarReserva: (reserva) =>
89:         set((state) => {
90:           const existe = state.reservas.some((r) => r.id === reserva.id);
91:           if (existe) {
92:             return {
93:               reservas: state.reservas.map((r) =>
94:                 r.id === reserva.id ? reserva : r
95:               ),
96:             };
97:           }
98:           return { reservas: [reserva, ...state.reservas] };
99:         }),
100: 
101:       atualizarReserva: (id, dados) =>
102:         set((state) => ({
103:           reservas: state.reservas.map((r) =>
104:             r.id === id ? { ...r, ...dados } : r
105:           ),
106:         })),
107: 
108:       removerReserva: (id) =>
109:         set((state) => ({
110:           reservas: state.reservas.filter((r) => r.id !== id),
111:         })),
112: 
113:       getReservaById: (id) => get().reservas.find((r) => r.id === id),
114: 
115:       getReservasPorData: (data) =>
116:         get().reservas.filter((r) => r.data === data),
117:     }),
118:     {
119:       name: "reservei-v2", // versão da chave no LocalStorage (usada como cache/fallback)
120:       partialize: (state) => ({ reservas: state.reservas }),
121:     }
122:   )
123: );
