211:       }
212:     )
213:     .on(
214:       "postgres_changes",
215:       {
216:         event: "UPDATE",
217:         schema: "public",
218:         table: TABELA_RESERVAS,
219:       },
220:       (payload) => {
221:         const atualizada = rowToReserva(payload.new as ReservaDbRow);
222:         onUpdate(atualizada);
223:       }
224:     )
225:     .on(
226:       "postgres_changes",
227:       {
228:         event: "DELETE",
229:         schema: "public",
230:         table: TABELA_RESERVAS,
231:       },
232:       (payload) => {
233:         const idDeletado = (payload.old as { id?: string })?.id;
234:         if (idDeletado) {
235:           onDelete(idDeletado);
236:         }
237:       }
238:     )
