/**
 * Tipos de domínio e DTOs da Agenda Completa do Administrador.
 * Fornece interfaces para Calendário Mensal, Grade Diária, Reservas Manuais e Bloqueios.
 */

import type { Esporte } from "@/lib/quadras";
import type { Reserva } from "@/store/useReservasStore";

/**
 * Classificação detalhada da ocupação de um determinado horário (slot) na visão do admin.
 */
export type TipoOcupacaoSlot =
  | "disponivel"
  | "cliente_online"
  | "admin_manual"
  | "manutencao_bloqueio"
  | "escolinha"
  | "grupo";

/**
 * Representação de um slot de horário na grade diária de uma quadra para o administrador.
 */
export interface SlotAgendaAdmin {
  horario: string;
  horaFim: string;
  quadraId: string;
  data: string;
  tipo: TipoOcupacaoSlot;
  reserva?: Reserva;
  nomeExibicao?: string;
  pago?: boolean;
  motivoBloqueio?: string;
}

/**
 * Dados informados pelo administrador para criar uma reserva manual.
 */
export interface DadosCriacaoReservaManual {
  quadraId: string;
  data: string;
  horarios: string[];
  nomeCliente: string;
  whatsappCliente?: string;
  esporte?: Esporte;
  /** Indica se o cliente já realizou o pagamento integral no balcão/Pix */
  pago: boolean;
  /** Valor cobrado pela reserva (se omitido, calcula com base na tabela da quadra) */
  valorTotal?: number;
  observacoes?: string;
}

/**
 * Dados informados pelo administrador para bloquear um ou mais horários de uma quadra.
 */
export interface DadosCriacaoBloqueio {
  quadraId: string;
  data: string;
  horarios: string[];
  motivo: string;
  observacoes?: string;
}

/**
 * Informações resumidas de um dia específico exibido no grid do calendário mensal.
 */
export interface DiaCalendarioMensal {
  data: string;
  diaNumero: number;
  diaSemana: number; // 0 = Domingo, 6 = Sábado
  mesAtual: boolean;
  isHoje: boolean;
  totalReservas: number;
  totalBloqueios: number;
  totalHorariosOcupados: number;
}

/**
 * Resumo dos totais de ocupação do mês visualizado.
 */
export interface ResumoMesAdmin {
  ano: number;
  mes: number;
  totalReservas: number;
  totalBloqueios: number;
  totalHorariosOcupados: number;
  diasComReservas: number;
}

/**
 * Resultado da validação ou execução de uma operação na agenda.
 */
export interface ResultadoOperacaoAgenda {
  ok: boolean;
  motivo?: string;
  reserva?: Reserva;
  conflitoCom?: Reserva;
}

/**
 * Motivos pré-definidos sugeridos para bloqueio de horários.
 */
export const MOTIVOS_BLOQUEIO_SUGERIDOS = [
  "Manutenção preventiva de piso",
  "Troca de rede e iluminação",
  "Pintura e demarcação",
  "Chuva / Infiltração na cobertura",
  "Evento fechado da diretoria",
  "Limpeza profunda e higienização",
  "Outro motivo administrativo",
] as const;

/**
 * Serviço de Lógica de Negócio pura para a Agenda Completa do Administrador.
 * Implementa validação de conflitos, bloqueios, reservas manuais e agregação mensal.
 *
 * Princípio: Funções puras e desacopladas de componentes React, facilitando testes de unidade e regras de negócio.
 */

import { HORARIOS_DISPONIVEIS, QUADRAS } from "@/lib/quadras";
import { calcularValorTotal, saoConsecutivos } from "@/lib/constants";
import type { Reserva } from "@/store/useReservasStore";
import type {
  DadosCriacaoBloqueio,
  DadosCriacaoReservaManual,
  DiaCalendarioMensal,
  ResumoMesAdmin,
  SlotAgendaAdmin,
  TipoOcupacaoSlot,
} from "./types";

/**
 * Número máximo de meses no futuro que o administrador pode navegar na agenda.
 * Conforme critério de aceitação: histórico até 6 meses no futuro.
 */
export const LIMITE_MESES_FUTURO = 6;

/**
 * Classifica a ocupação de um horário individual com base nos dados da reserva.
 *
 * @param reserva Objeto de reserva ou undefined caso o horário esteja livre.
 * @returns Tipo de ocupação padronizado.
 */
export function classificarTipoSlot(reserva?: Reserva): TipoOcupacaoSlot {
  if (!reserva || reserva.status === "cancelada") {
    return "disponivel";
  }

  if (reserva.tipoReserva === "manutencao_bloqueio") {
    return "manutencao_bloqueio";
  }

  if (reserva.tipoReserva === "admin_manual") {
    return "admin_manual";
  }

  if (reserva.tipoReserva === "escolinha") {
    return "escolinha";
  }

  if (reserva.tipoReserva === "grupo") {
    return "grupo";
  }

  return "cliente_online";
}

/**
 * Monta todos os slots de uma quadra para um determinado dia, identificando
 * a ocupação e detalhes de cada horário (08:00 até 22:00).
 *
 * @param quadraId Identificador da quadra (ex: "q1")
 * @param data Data no formato YYYY-MM-DD
 * @param reservas Lista de reservas ativas
 * @returns Lista ordenada de slots com seus respectivos metadados
 */
export function montarSlotsQuadraDia(
  quadraId: string,
  data: string,
  reservas: Reserva[]
): SlotAgendaAdmin[] {
  // Filtra reservas da quadra e data que não estão canceladas
  const reservasDoDia = reservas.filter(
    (r) => r.quadraId === quadraId && r.data === data && r.status !== "cancelada"
  );

  return HORARIOS_DISPONIVEIS.map((horario) => {
    const horaNum = parseInt(horario.split(":")[0], 10);
    const horaFim = `${String(horaNum + 1).padStart(2, "0")}:00`;

    // Localiza a reserva que ocupa este slot de horário
    const reserva = reservasDoDia.find((r) => r.horarios.includes(horario));
    const tipo = classificarTipoSlot(reserva);

    let nomeExibicao: string | undefined;
    let pago: boolean | undefined;
    let motivoBloqueio: string | undefined;

    if (reserva) {
      nomeExibicao = reserva.nomeCliente;
      pago = reserva.status === "confirmada" || reserva.valorPendente === 0;

      if (tipo === "manutencao_bloqueio") {
        motivoBloqueio = reserva.observacoes || reserva.nomeCliente || "Bloqueado pelo Admin";
      }
    }

    return {
      horario,
      horaFim,
      quadraId,
      data,
      tipo,
      reserva,
      nomeExibicao,
      pago,
      motivoBloqueio,
    };
  });
}

/**
 * Validação rigorosa para impedir que um administrador bloqueie um horário que já possua
 * reservas ativas. Conforme a regra de negócio da spec:
 * "O sistema deve IMPEDIR o admin de bloquear um horário que já possua uma reserva.
 *  O admin receberá um alerta e deverá gerenciar a reserva existente antes de efetuar o bloqueio."
 *
 * @param quadraId Identificador da quadra
 * @param data Data do bloqueio no formato YYYY-MM-DD
 * @param horarios Lista de horários que se deseja bloquear
 * @param reservasExistentes Lista completa de reservas
 * @returns Objeto indicando se a ação é válida ou detalhes do conflito
 */
export function validarConflitoBloqueio(
  quadraId: string,
  data: string,
  horarios: string[],
  reservasExistentes: Reserva[]
): { valido: boolean; motivo?: string; conflitoCom?: Reserva } {
  if (!quadraId || !QUADRAS.some((q) => q.id === quadraId)) {
    return { valido: false, motivo: "Selecione uma quadra válida para o bloqueio." };
  }

  if (!data || !/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return { valido: false, motivo: "Informe uma data válida no formato AAAA-MM-DD." };
  }

  if (!horarios || horarios.length === 0) {
    return { valido: false, motivo: "Selecione ao menos um horário para aplicar o bloqueio." };
  }

  // Verifica se há alguma reserva ativa (que não seja outro bloqueio cancelado) que colide
  const reservaConflitante = reservasExistentes.find(
    (r) =>
      r.quadraId === quadraId &&
      r.data === data &&
      r.status !== "cancelada" &&
      r.horarios.some((h) => horarios.includes(h))
  );

  if (reservaConflitante) {
    const quadraNome = QUADRAS.find((q) => q.id === quadraId)?.nome ?? quadraId;
    const ehBloqueio = reservaConflitante.tipoReserva === "manutencao_bloqueio";

    if (ehBloqueio) {
      return {
        valido: false,
        motivo: `O horário já está bloqueado (${reservaConflitante.nomeCliente}) na ${quadraNome}.`,
        conflitoCom: reservaConflitante,
      };
    }

    return {
      valido: false,
      motivo: `Não é possível bloquear este horário pois já existe uma reserva para "${reservaConflitante.nomeCliente}" (${reservaConflitante.horaInicio} às ${reservaConflitante.horaFim}) na ${quadraNome}. Por favor, entre em contato com o cliente e cancele ou remaneje a reserva antes de aplicar o bloqueio.`,
      conflitoCom: reservaConflitante,
    };
  }

  return { valido: true };
}

/**
 * Valida a criação de uma reserva manual pelo administrador.
 *
 * @param dados Dados submetidos no formulário
 * @param reservasExistentes Lista de reservas atuais para detecção de choque
 * @returns Objeto com lista de erros e eventual reserva conflitante
 */
export function validarReservaManual(
  dados: DadosCriacaoReservaManual,
  reservasExistentes: Reserva[]
): { valido: boolean; erros: string[]; conflitoCom?: Reserva } {
  const erros: string[] = [];

  if (!dados.nomeCliente || dados.nomeCliente.trim().length === 0) {
    erros.push("Informe o nome do cliente ou do grupo responsável.");
  }

  if (!dados.quadraId || !QUADRAS.some((q) => q.id === dados.quadraId)) {
    erros.push("Selecione uma quadra válida.");
  }

  if (!dados.data || !/^\d{4}-\d{2}-\d{2}$/.test(dados.data)) {
    erros.push("Informe uma data válida.");
  }

  if (!dados.horarios || dados.horarios.length === 0) {
    erros.push("Selecione pelo menos um horário de jogo.");
  } else {
    // Horários devem ser consecutivos
    const horariosOrdenados = [...dados.horarios].sort();
    if (!saoConsecutivos(horariosOrdenados)) {
      erros.push("Os horários selecionados devem ser consecutivos (sem intervalos).");
    }

    // Choque de horários
    const conflito = reservasExistentes.find(
      (r) =>
        r.quadraId === dados.quadraId &&
        r.data === dados.data &&
        r.status !== "cancelada" &&
        r.horarios.some((h) => dados.horarios.includes(h))
    );

    if (conflito) {
      if (conflito.tipoReserva === "manutencao_bloqueio") {
        erros.push(
          `O horário está bloqueado para manutenção (${conflito.nomeCliente}). Remova o bloqueio antes de reservar.`
        );
      } else {
        erros.push(
          `O horário já está ocupado por "${conflito.nomeCliente}" (${conflito.horaInicio} às ${conflito.horaFim}).`
        );
      }
      return { valido: false, erros, conflitoCom: conflito };
    }
  }

  return { valido: erros.length === 0, erros };
}

/**
 * Cria o objeto da entidade Reserva formatado para uma Reserva Manual do Administrador.
 *
 * @param dados Dados validados da reserva manual
 * @returns Instância de Reserva pronta para persistência
 */
export function construirReservaManual(dados: DadosCriacaoReservaManual): Reserva {
  const horariosOrdenados = [...dados.horarios].sort();
  const valorCalculado =
    typeof dados.valorTotal === "number" && dados.valorTotal >= 0
      ? dados.valorTotal
      : calcularValorTotal(horariosOrdenados);

  const horaInicio = horariosOrdenados[0];
  const ultimoSlot = parseInt(horariosOrdenados[horariosOrdenados.length - 1].split(":")[0], 10);
  const horaFim = `${String(ultimoSlot + 1).padStart(2, "0")}:00`;

  const id = `rsv_adm_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;

  return {
    id,
    quadraId: dados.quadraId,
    nomeCliente: dados.nomeCliente.trim(),
    whatsappCliente: dados.whatsappCliente ? dados.whatsappCliente.trim() : "",
    cpfCliente: "",
    data: dados.data,
    horarios: horariosOrdenados,
    horaInicio,
    horaFim,
    valorTotal: valorCalculado,
    valorSinal: dados.pago ? valorCalculado : 0,
    valorPendente: dados.pago ? 0 : valorCalculado,
    status: dados.pago ? "confirmada" : "pendente",
    statusWhatsApp: "nao_enviado",
    criadaEm: new Date().toISOString(),
    esporte: dados.esporte,
    observacoes: dados.observacoes ? dados.observacoes.trim() : undefined,
    tipoReserva: "admin_manual",
  };
}

/**
 * Cria o objeto da entidade Reserva formatado para um Bloqueio de Manutenção/Administrativo.
 * Importante: O valor total é 0 e não contabiliza no faturamento do complexo.
 *
 * @param dados Dados do bloqueio
 * @returns Instância de Reserva representando o bloqueio
 */
export function construirBloqueio(dados: DadosCriacaoBloqueio): Reserva {
  const horariosOrdenados = [...dados.horarios].sort();
  const horaInicio = horariosOrdenados[0];
  const ultimoSlot = parseInt(horariosOrdenados[horariosOrdenados.length - 1].split(":")[0], 10);
  const horaFim = `${String(ultimoSlot + 1).padStart(2, "0")}:00`;

  const id = `bloq_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
  const motivoLimpo = dados.motivo.trim();
  const obsCompleta = dados.observacoes?.trim()
    ? `${motivoLimpo} - ${dados.observacoes.trim()}`
    : motivoLimpo;

  return {
    id,
    quadraId: dados.quadraId,
    nomeCliente: `Bloqueio: ${motivoLimpo}`,
    whatsappCliente: "",
    cpfCliente: "",
    data: dados.data,
    horarios: horariosOrdenados,
    horaInicio,
    horaFim,
    valorTotal: 0,
    valorSinal: 0,
    valorPendente: 0,
    status: "confirmada",
    statusWhatsApp: "nao_enviado",
    criadaEm: new Date().toISOString(),
    observacoes: obsCompleta,
    tipoReserva: "manutencao_bloqueio",
  };
}

/**
 * Gera a matriz de dias para a exibição de um mês tradicional de calendário (Domingo a Sábado),
 * incluindo os dias de preenchimento dos meses adjacentes e agregando as reservas de cada dia.
 *
 * @param ano Ano com 4 dígitos (ex.: 2026)
 * @param mes Mês de 1 a 12 (ex.: 10 para Outubro)
 * @param reservas Lista de reservas para agregação diária
 * @param hojeStr Data atual no formato "YYYY-MM-DD"
 * @returns Lista completa de dias do grid (normalmente 35 ou 42 células)
 */
export function gerarDiasCalendarioMensal(
  ano: number,
  mes: number,
  reservas: Reserva[],
  hojeStr: string
): DiaCalendarioMensal[] {
  // Primeiro dia do mês (0 = domingo ... 6 = sábado)
  const primeiroDiaDoMes = new Date(ano, mes - 1, 1);
  const diaSemanaInicio = primeiroDiaDoMes.getDay();

  // Quantidade de dias no mês atual
  const totalDiasMes = new Date(ano, mes, 0).getDate();

  // Quantidade de dias no mês anterior
  const totalDiasMesAnterior = new Date(ano, mes - 1, 0).getDate();

  const grid: DiaCalendarioMensal[] = [];

  // Mapeia reservas por data para busca instantânea O(1)
  const mapaReservasPorData = new Map<string, Reserva[]>();
  for (const r of reservas) {
    if (r.status === "cancelada") continue;
    const lista = mapaReservasPorData.get(r.data) || [];
    lista.push(r);
    mapaReservasPorData.set(r.data, lista);
  }

  function criarDia(dataIso: string, diaNumero: number, diaSemana: number, mesAtual: boolean): DiaCalendarioMensal {
    const doDia = mapaReservasPorData.get(dataIso) || [];
    let totalBloqueios = 0;
    let totalReservas = 0;
    let totalHorariosOcupados = 0;

    for (const r of doDia) {
      if (r.tipoReserva === "manutencao_bloqueio") {
        totalBloqueios++;
      } else {
        totalReservas++;
      }
      totalHorariosOcupados += r.horarios.length;
    }

    return {
      data: dataIso,
      diaNumero,
      diaSemana,
      mesAtual,
      isHoje: dataIso === hojeStr,
      totalReservas,
      totalBloqueios,
      totalHorariosOcupados,
    };
  }

  // 1. Preenchimento dos dias finais do mês anterior
  const anoAnt = mes === 1 ? ano - 1 : ano;
  const mesAnt = mes === 1 ? 12 : mes - 1;
  for (let i = diaSemanaInicio - 1; i >= 0; i--) {
    const diaNum = totalDiasMesAnterior - i;
    const dataIso = `${anoAnt}-${String(mesAnt).padStart(2, "0")}-${String(diaNum).padStart(2, "0")}`;
    const diaSemana = (diaSemanaInicio - 1 - i) % 7;
    grid.push(criarDia(dataIso, diaNum, diaSemana, false));
  }

  // 2. Dias do mês atual
  for (let dia = 1; dia <= totalDiasMes; dia++) {
    const dataIso = `${ano}-${String(mes).padStart(2, "0")}-${String(dia).padStart(2, "0")}`;
    const diaSemana = (diaSemanaInicio + dia - 1) % 7;
    grid.push(criarDia(dataIso, dia, diaSemana, true));
  }

  // 3. Preenchimento dos dias iniciais do próximo mês para completar a última semana
  const restoSemana = grid.length % 7;
  if (restoSemana !== 0) {
    const diasParaCompletar = 7 - restoSemana;
    const anoProx = mes === 12 ? ano + 1 : ano;
    const mesProx = mes === 12 ? 1 : mes + 1;

    for (let dia = 1; dia <= diasParaCompletar; dia++) {
      const dataIso = `${anoProx}-${String(mesProx).padStart(2, "0")}-${String(dia).padStart(2, "0")}`;
      const diaSemana = (grid.length) % 7;
      grid.push(criarDia(dataIso, dia, diaSemana, false));
    }
  }

  return grid;
}

/**
 * Calcula o resumo consolidado de ocupação do mês.
 *
 * @param ano Ano com 4 dígitos
 * @param mes Mês de 1 a 12
 * @param dias Lista de dias gerados para o mês
 * @returns Estatísticas consolidadas
 */
export function calcularResumoMes(
  ano: number,
  mes: number,
  dias: DiaCalendarioMensal[]
): ResumoMesAdmin {
  const diasMesAtual = dias.filter((d) => d.mesAtual);

  let totalReservas = 0;
  let totalBloqueios = 0;
  let totalHorariosOcupados = 0;
  let diasComReservas = 0;

  for (const d of diasMesAtual) {
    totalReservas += d.totalReservas;
    totalBloqueios += d.totalBloqueios;
    totalHorariosOcupados += d.totalHorariosOcupados;
    if (d.totalReservas > 0) {
      diasComReservas++;
    }
  }

  return {
    ano,
    mes,
    totalReservas,
    totalBloqueios,
    totalHorariosOcupados,
    diasComReservas,
  };
}

/**
 * Verifica se a navegação temporal para determinado mês é permitida.
 * Permite retroceder ao passado ilimitadamente e avançar até LIMITE_MESES_FUTURO meses à frente.
 *
 * @param ano Ano atual exibido
 * @param mes Mês atual exibido (1..12)
 * @param dataReferencia Data base (geralmente data de hoje)
 * @returns Indicadores booleanos para navegação anterior/posterior
 */
export function isNavegacaoMesPermitida(
  ano: number,
  mes: number,
  dataReferencia: Date = new Date()
): { podeVoltar: boolean; podeAvancar: boolean } {
  const refAno = dataReferencia.getFullYear();
  const refMes = dataReferencia.getMonth() + 1; // 1..12

  // Diferença em meses entre o mês alvo e a referência de hoje
  const diferencaMeses = (ano - refAno) * 12 + (mes - refMes);

  return {
    podeVoltar: true, // Sempre pode consultar o histórico passado
    podeAvancar: diferencaMeses < LIMITE_MESES_FUTURO,
  };
}

/**
 * Retorna o nome por extenso do mês em Português.
 */
export function getNomeMesExtenso(mes: number): string {
  const nomes = [
    "Janeiro",
    "Fevereiro",
    "Março",
    "Abril",
    "Maio",
    "Junho",
    "Julho",
    "Agosto",
    "Setembro",
    "Outubro",
    "Novembro",
    "Dezembro",
  ];
  return nomes[mes - 1] ?? "";
}

import { describe, it, expect } from "vitest";
import {
  classificarTipoSlot,
  montarSlotsQuadraDia,
  validarConflitoBloqueio,
  validarReservaManual,
  construirReservaManual,
  construirBloqueio,
  gerarDiasCalendarioMensal,
  calcularResumoMes,
  isNavegacaoMesPermitida,
  getNomeMesExtenso,
  LIMITE_MESES_FUTURO,
} from "@/lib/adminAgenda/adminAgendaService";
import type { Reserva } from "@/store/useReservasStore";

// ─── Helpers de Criação de Reservas para Teste ─────────────────────────────────

function criarReservaMock(parcial: Partial<Reserva>): Reserva {
  return {
    id: parcial.id ?? "rsv_mock_1",
    quadraId: parcial.quadraId ?? "q1",
    nomeCliente: parcial.nomeCliente ?? "Carlos Silva",
    whatsappCliente: parcial.whatsappCliente ?? "11999998888",
    cpfCliente: parcial.cpfCliente ?? "12345678900",
    data: parcial.data ?? "2026-10-15",
    horarios: parcial.horarios ?? ["18:00", "19:00"],
    horaInicio: parcial.horaInicio ?? "18:00",
    horaFim: parcial.horaFim ?? "20:00",
    valorTotal: parcial.valorTotal ?? 180,
    valorSinal: parcial.valorSinal ?? 72,
    valorPendente: parcial.valorPendente ?? 108,
    status: parcial.status ?? "confirmada",
    statusWhatsApp: parcial.statusWhatsApp ?? "nao_enviado",
    criadaEm: parcial.criadaEm ?? "2026-10-01T10:00:00Z",
    tipoReserva: parcial.tipoReserva,
    observacoes: parcial.observacoes,
  };
}

describe("adminAgendaService - Testes de Unidade e Regras de Negócio", () => {
  // ─── 1. Classificação do Slot ───────────────────────────────────────────────
  describe("classificarTipoSlot", () => {
    it("deve classificar como 'disponivel' quando reserva for undefined", () => {
      expect(classificarTipoSlot(undefined)).toBe("disponivel");
    });

    it("deve classificar como 'disponivel' quando reserva estiver cancelada", () => {
      const cancelada = criarReservaMock({ status: "cancelada" });
      expect(classificarTipoSlot(cancelada)).toBe("disponivel");
    });

    it("deve classificar como 'manutencao_bloqueio' quando for bloqueio administrativo", () => {
      const bloqueio = criarReservaMock({ tipoReserva: "manutencao_bloqueio" });
      expect(classificarTipoSlot(bloqueio)).toBe("manutencao_bloqueio");
    });

    it("deve classificar como 'admin_manual' quando for reserva criada pelo admin", () => {
      const manual = criarReservaMock({ tipoReserva: "admin_manual" });
      expect(classificarTipoSlot(manual)).toBe("admin_manual");
    });

    it("deve classificar como 'escolinha' e 'grupo' conforme o tipo", () => {
      expect(classificarTipoSlot(criarReservaMock({ tipoReserva: "escolinha" }))).toBe("escolinha");
      expect(classificarTipoSlot(criarReservaMock({ tipoReserva: "grupo" }))).toBe("grupo");
    });

    it("deve classificar como 'cliente_online' para reserva avulsa comum", () => {
      expect(classificarTipoSlot(criarReservaMock({ tipoReserva: "avulsa" }))).toBe("cliente_online");
      expect(classificarTipoSlot(criarReservaMock({ tipoReserva: undefined }))).toBe("cliente_online");
    });
  });

  // ─── 2. Montagem dos Slots da Quadra ─────────────────────────────────────────
  describe("montarSlotsQuadraDia", () => {
    it("deve retornar todos os 15 horários operacionais do complexo", () => {
      const slots = montarSlotsQuadraDia("q1", "2026-10-15", []);
      expect(slots).toHaveLength(15);
      expect(slots[0].horario).toBe("08:00");
      expect(slots[14].horario).toBe("22:00");
      expect(slots.every((s) => s.tipo === "disponivel")).toBe(true);
    });

    it("deve identificar corretamente os horários ocupados por reservas", () => {
      const reserva = criarReservaMock({
        quadraId: "q1",
        data: "2026-10-15",
        horarios: ["14:00", "15:00"],
        tipoReserva: "admin_manual",
        nomeCliente: "Pelada dos Amigos",
      });

      const slots = montarSlotsQuadraDia("q1", "2026-10-15", [reserva]);
      const slot14 = slots.find((s) => s.horario === "14:00");
      const slot15 = slots.find((s) => s.horario === "15:00");
      const slot16 = slots.find((s) => s.horario === "16:00");

      expect(slot14?.tipo).toBe("admin_manual");
      expect(slot14?.nomeExibicao).toBe("Pelada dos Amigos");
      expect(slot15?.tipo).toBe("admin_manual");
      expect(slot16?.tipo).toBe("disponivel");
    });

    it("não deve considerar reservas de outras quadras ou de outros dias", () => {
      const reservaOutraQuadra = criarReservaMock({
        quadraId: "q2",
        data: "2026-10-15",
        horarios: ["14:00"],
      });
      const reservaOutroDia = criarReservaMock({
        quadraId: "q1",
        data: "2026-10-16",
        horarios: ["14:00"],
      });

      const slots = montarSlotsQuadraDia("q1", "2026-10-15", [
        reservaOutraQuadra,
        reservaOutroDia,
      ]);
      const slot14 = slots.find((s) => s.horario === "14:00");
      expect(slot14?.tipo).toBe("disponivel");
    });
  });

  // ─── 3. Validação de Conflito para Bloqueio (Regra de Ouro) ─────────────────
  describe("validarConflitoBloqueio", () => {
    it("deve permitir o bloqueio quando o horário estiver totalmente livre", () => {
      const resultado = validarConflitoBloqueio("q1", "2026-10-15", ["10:00", "11:00"], []);
      expect(resultado.valido).toBe(true);
      expect(resultado.motivo).toBeUndefined();
    });

    it("deve IMPEDIR o bloqueio quando houver reserva ativa de cliente no horário", () => {
      const reserva = criarReservaMock({
        quadraId: "q1",
        data: "2026-10-15",
        horarios: ["10:00", "11:00"],
        nomeCliente: "Fernando Souza",
        horaInicio: "10:00",
        horaFim: "12:00",
        status: "confirmada",
      });

      const resultado = validarConflitoBloqueio(
        "q1",
        "2026-10-15",
        ["11:00", "12:00"],
        [reserva]
      );

      expect(resultado.valido).toBe(false);
      expect(resultado.motivo).toContain("Não é possível bloquear este horário pois já existe uma reserva");
      expect(resultado.motivo).toContain("Fernando Souza");
      expect(resultado.conflitoCom?.id).toBe(reserva.id);
    });

    it("deve permitir o bloqueio se a reserva existente estiver cancelada", () => {
      const cancelada = criarReservaMock({
        quadraId: "q1",
        data: "2026-10-15",
        horarios: ["10:00"],
        status: "cancelada",
      });

      const resultado = validarConflitoBloqueio("q1", "2026-10-15", ["10:00"], [cancelada]);
      expect(resultado.valido).toBe(true);
    });

    it("deve impedir o bloqueio se já houver outro bloqueio no mesmo horário", () => {
      const bloqueioExistente = criarReservaMock({
        quadraId: "q1",
        data: "2026-10-15",
        horarios: ["14:00"],
        tipoReserva: "manutencao_bloqueio",
        nomeCliente: "Bloqueio: Pintura",
      });

      const resultado = validarConflitoBloqueio("q1", "2026-10-15", ["14:00"], [bloqueioExistente]);
      expect(resultado.valido).toBe(false);
      expect(resultado.motivo).toContain("já está bloqueado");
    });

    it("deve rejeitar quadra ou data inválida", () => {
      expect(validarConflitoBloqueio("quadra_fantasma", "2026-10-15", ["10:00"], []).valido).toBe(false);
      expect(validarConflitoBloqueio("q1", "data-invalida", ["10:00"], []).valido).toBe(false);
      expect(validarConflitoBloqueio("q1", "2026-10-15", [], []).valido).toBe(false);
    });
  });

  // ─── 4. Validação de Reserva Manual ─────────────────────────────────────────
  describe("validarReservaManual", () => {
    it("deve aprovar reserva manual válida", () => {
      const resultado = validarReservaManual(
        {
          quadraId: "q1",
          data: "2026-10-15",
          horarios: ["18:00", "19:00"],
          nomeCliente: "Grupo da Quinta",
          pago: false,
        },
        []
      );

      expect(resultado.valido).toBe(true);
      expect(resultado.erros).toHaveLength(0);
    });

    it("deve reprovar quando nome do cliente for vazio", () => {
      const resultado = validarReservaManual(
        {
          quadraId: "q1",
          data: "2026-10-15",
          horarios: ["18:00"],
          nomeCliente: "   ",
          pago: false,
        },
        []
      );

      expect(resultado.valido).toBe(false);
      expect(resultado.erros).toContain("Informe o nome do cliente ou do grupo responsável.");
    });

    it("deve reprovar quando horários não forem consecutivos", () => {
      const resultado = validarReservaManual(
        {
          quadraId: "q1",
          data: "2026-10-15",
          horarios: ["14:00", "16:00"],
          nomeCliente: "Lucas",
          pago: false,
        },
        []
      );

      expect(resultado.valido).toBe(false);
      expect(resultado.erros).toContain("Os horários selecionados devem ser consecutivos (sem intervalos).");
    });

    it("deve reprovar quando houver choque com reserva ou bloqueio existente", () => {
      const bloqueio = criarReservaMock({
        quadraId: "q1",
        data: "2026-10-15",
        horarios: ["18:00"],
        tipoReserva: "manutencao_bloqueio",
        nomeCliente: "Bloqueio: Manutenção Elétrica",
      });

      const resultado = validarReservaManual(
        {
          quadraId: "q1",
          data: "2026-10-15",
          horarios: ["18:00", "19:00"],
          nomeCliente: "Equipe Alpha",
          pago: true,
        },
        [bloqueio]
      );

      expect(resultado.valido).toBe(false);
      expect(resultado.erros[0]).toContain("O horário está bloqueado para manutenção");
    });
  });

  // ─── 5. Criação das Entidades ───────────────────────────────────────────────
  describe("construirReservaManual e construirBloqueio", () => {
    it("deve construir reserva manual com status pago (confirmada) e valores zerados de pendência", () => {
      const reserva = construirReservaManual({
        quadraId: "q1",
        data: "2026-10-20",
        horarios: ["19:00", "20:00"],
        nomeCliente: "Mariana Costa",
        whatsappCliente: "11988887777",
        pago: true,
        esporte: "Futsal",
        observacoes: "Pagou via Pix no balcão",
      });

      expect(reserva.id).toMatch(/^rsv_adm_/);
      expect(reserva.tipoReserva).toBe("admin_manual");
      expect(reserva.status).toBe("confirmada");
      expect(reserva.valorSinal).toBe(reserva.valorTotal);
      expect(reserva.valorPendente).toBe(0);
      expect(reserva.horaInicio).toBe("19:00");
      expect(reserva.horaFim).toBe("21:00");
      expect(reserva.esporte).toBe("Futsal");
    });

    it("deve construir reserva manual com status pendente quando pago=false", () => {
      const reserva = construirReservaManual({
        quadraId: "q2",
        data: "2026-10-20",
        horarios: ["14:00"],
        nomeCliente: "João Pedro",
        pago: false,
      });

      expect(reserva.status).toBe("pendente");
      expect(reserva.valorSinal).toBe(0);
      expect(reserva.valorPendente).toBe(reserva.valorTotal);
    });

    it("deve construir bloqueio de manutenção com valor total zero e status confirmada", () => {
      const bloqueio = construirBloqueio({
        quadraId: "q3",
        data: "2026-10-25",
        horarios: ["08:00", "09:00"],
        motivo: "Troca dos refletores",
        observacoes: "Equipe técnica autorizada",
      });

      expect(bloqueio.id).toMatch(/^bloq_/);
      expect(bloqueio.tipoReserva).toBe("manutencao_bloqueio");
      expect(bloqueio.valorTotal).toBe(0);
      expect(bloqueio.valorSinal).toBe(0);
      expect(bloqueio.valorPendente).toBe(0);
      expect(bloqueio.nomeCliente).toBe("Bloqueio: Troca dos refletores");
      expect(bloqueio.observacoes).toContain("Equipe técnica autorizada");
      expect(bloqueio.status).toBe("confirmada");
    });
  });

  // ─── 6. Calendário Mensal e Navegação ─────────────────────────────────────────
  describe("gerarDiasCalendarioMensal e calcularResumoMes", () => {
    it("deve gerar o grid de dias com preenchimento correto para Outubro de 2026", () => {
      const reserva1 = criarReservaMock({ data: "2026-10-10", horarios: ["10:00", "11:00"] });
      const bloqueio1 = criarReservaMock({
        data: "2026-10-15",
        horarios: ["14:00"],
        tipoReserva: "manutencao_bloqueio",
      });

      const dias = gerarDiasCalendarioMensal(2026, 10, [reserva1, bloqueio1], "2026-10-05");

      // Grid deve ser múltiplo de 7 (semanas completas)
      expect(dias.length % 7).toBe(0);
      expect(dias.length).toBeGreaterThanOrEqual(35);

      // Encontra o dia 10 e o dia 15
      const dia10 = dias.find((d) => d.data === "2026-10-10");
      const dia15 = dias.find((d) => d.data === "2026-10-15");
      const diaHoje = dias.find((d) => d.data === "2026-10-05");

      expect(dia10?.totalReservas).toBe(1);
      expect(dia10?.totalBloqueios).toBe(0);
      expect(dia10?.totalHorariosOcupados).toBe(2);

      expect(dia15?.totalReservas).toBe(0);
      expect(dia15?.totalBloqueios).toBe(1);
      expect(dia15?.totalHorariosOcupados).toBe(1);

      expect(diaHoje?.isHoje).toBe(true);

      const resumo = calcularResumoMes(2026, 10, dias);
      expect(resumo.totalReservas).toBe(1);
      expect(resumo.totalBloqueios).toBe(1);
      expect(resumo.totalHorariosOcupados).toBe(3);
      expect(resumo.diasComReservas).toBe(1);
    });

    it("deve respeitar a regra de limite de 6 meses no futuro para navegação", () => {
      const hoje = new Date(2026, 9, 5); // 05/10/2026 (mês 9 = Outubro)

      // Outubro 2026 (mês atual)
      const mesAtual = isNavegacaoMesPermitida(2026, 10, hoje);
      expect(mesAtual.podeVoltar).toBe(true);
      expect(mesAtual.podeAvancar).toBe(true);

      // Passado: Outubro 2025 (1 ano atrás) -> permitido
      const anoPassado = isNavegacaoMesPermitida(2025, 10, hoje);
      expect(anoPassado.podeVoltar).toBe(true);
      expect(anoPassado.podeAvancar).toBe(true);

      // Futuro permitido: Abril 2027 (+6 meses)
      const seisMesesFrente = isNavegacaoMesPermitida(2027, 4, hoje);
      expect(seisMesesFrente.podeAvancar).toBe(false);

      // Futuro proibido: Maio 2027 (+7 meses)
      const seteMesesFrente = isNavegacaoMesPermitida(2027, 5, hoje);
      expect(seteMesesFrente.podeAvancar).toBe(false);
    });

    it("deve retornar o nome correto do mês em português", () => {
      expect(getNomeMesExtenso(1)).toBe("Janeiro");
      expect(getNomeMesExtenso(10)).toBe("Outubro");
      expect(getNomeMesExtenso(12)).toBe("Dezembro");
    });
  });
});

