import { QUADRAS, ESPORTES, type Esporte, HORARIOS_DISPONIVEIS } from "@/lib/quadras";
import { calcularValorTotal, formatarMoeda, formatarDataExibicao, saoConsecutivos } from "@/lib/constants";
import { useReservasService } from "@/hooks/useReservasService";
import { toast } from "sonner";

interface Props {
  aberto: boolean;
  quadraIdPadrao?: string;
  dataPadrao?: string;
  horariosPadrao?: string[];
  onFechar: () => void;
  onSucesso?: () => void;
}

export function ModalReservaManual({
  aberto,
  quadraIdPadrao,
  dataPadrao,
  horariosPadrao,
  onFechar,
  onSucesso,
}: Props) {
  const { reservas, criarReservaManual } = useReservasService();

  const [quadraId, setQuadraId] = useState(quadraIdPadrao || "q1");
  const [data, setData] = useState(dataPadrao || new Date().toISOString().split("T")[0]);
  const [horarios, setHorarios] = useState<string[]>(horariosPadrao || ["18:00"]);
  const [nomeCliente, setNomeCliente] = useState("");
  const [whatsappCliente, setWhatsappCliente] = useState("");
  const [esporte, setEsporte] = useState<Esporte>("Futsal");
  const [pago, setPago] = useState(false);
  const [valorCustomizado, setValorCustomizado] = useState<string>("");
  const [observacoes, setObservacoes] = useState("");
  const [salvando, setSalvando] = useState(false);

  // Sincroniza props iniciais quando o modal abre
  useEffect(() => {
    if (aberto) {
      if (quadraIdPadrao) setQuadraId(quadraIdPadrao);
      if (dataPadrao) setData(dataPadrao);
      if (horariosPadrao && horariosPadrao.length > 0) {
        setHorarios([...horariosPadrao].sort());
      }
      setNomeCliente("");
      setWhatsappCliente("");
      setPago(false);
      setValorCustomizado("");
      setObservacoes("");
    }
  }, [aberto, quadraIdPadrao, dataPadrao, horariosPadrao]);

  // Fechar no Escape
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") onFechar();
    },
    [onFechar]
  );

  useEffect(() => {
    if (!aberto) return;
    document.addEventListener("keydown", handleKeyDown);
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      document.body.style.overflow = "";
    };
  }, [aberto, handleKeyDown]);

  if (!aberto) return null;

  // Horários ocupados nesta quadra e data
  const horariosOcupados = reservas
    .filter(
      (r) =>
        r.quadraId === quadraId &&
        r.data === data &&
        r.status !== "cancelada"
    )
    .flatMap((r) => r.horarios);

  const valorPadrao = calcularValorTotal(horarios);
  const valorFinal = valorCustomizado !== "" ? parseFloat(valorCustomizado) || 0 : valorPadrao;

  function toggleHorario(h: string) {
    if (horariosOcupados.includes(h)) return;

    let proximo: string[];
    if (horarios.includes(h)) {
      proximo = horarios.filter((item) => item !== h);
    } else {
      proximo = [...horarios, h].sort();
    }

    if (proximo.length > 1 && !saoConsecutivos(proximo)) {
      toast.warning("Selecione horários consecutivos", {
        description: "Os horários de uma mesma reserva não devem ter intervalos.",
      });
      return;
    }

    setHorarios(proximo);
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    if (!nomeCliente.trim()) {
      toast.error("Informe o nome do cliente ou do grupo.");
      return;
    }

    if (horarios.length === 0) {
      toast.error("Selecione ao menos um horário.");
      return;
    }

    setSalvando(true);

    try {
      const res = await criarReservaManual({
        quadraId,
        data,
        horarios,
        nomeCliente: nomeCliente.trim(),
        whatsappCliente: whatsappCliente.trim(),
        esporte,
        pago,
        valorTotal: valorFinal,
        observacoes: observacoes.trim(),
      });

      if (!res.ok) {
        toast.error("Não foi possível criar a reserva", {
          description: res.motivo,
        });
        return;
      }

      toast.success("Reserva manual criada com sucesso!", {
        description: `Agendada para ${nomeCliente} em ${formatarDataExibicao(data)}.`,
      });

      onSucesso?.();
      onFechar();
    } finally {
      setSalvando(false);
    }
  }

  return (
    <>
      {/* Backdrop */}
      <div
        className="fixed inset-0 z-50 bg-black/75 backdrop-blur-sm animate-fade-in"
        onClick={onFechar}
      />

      {/* Modal Container */}
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4 pointer-events-none">
        <div className="bg-slate-900 border border-slate-700/60 rounded-2xl w-full max-w-xl shadow-2xl overflow-hidden pointer-events-auto max-h-[90vh] flex flex-col animate-scale-in">
          {/* Header */}
          <div className="flex items-center justify-between px-6 py-4 border-b border-slate-700/50 bg-slate-900 sticky top-0 z-10">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-xl bg-sky-500/10 border border-sky-500/20 flex items-center justify-center">
                <ShieldCheck className="w-4 h-4 text-sky-400" />
              </div>
              <div>
                <h2 className="text-base font-bold text-white leading-tight">
                  Nova Reserva Manual
                </h2>
                <p className="text-xs text-slate-400">
                  Agendamento administrativo pelo balcão ou WhatsApp
                </p>
              </div>
            </div>
            <button
              onClick={onFechar}
              className="w-8 h-8 flex items-center justify-center rounded-xl bg-slate-800 border border-slate-700 text-slate-400 hover:text-white transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
            {/* Linha 1: Quadra e Data */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                  <Layers className="w-3.5 h-3.5 text-slate-500" />
                  Quadra
                </label>
                <select
                  value={quadraId}
                  onChange={(e) => setQuadraId(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white focus:outline-none focus:border-sky-500 transition-colors"
                >
                  {QUADRAS.map((q) => (
                    <option key={q.id} value={q.id}>
                      Quadra {q.numero} (Poliesportiva)
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                  <Calendar className="w-3.5 h-3.5 text-slate-500" />
                  Data
                </label>
                <input
                  type="date"
                  value={data}
                  onChange={(e) => setData(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white focus:outline-none focus:border-sky-500 transition-colors"
                />
              </div>
            </div>

            {/* Linha 2: Horários (Seleção múltipla por pills) */}
            <div>
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center justify-between">
                <span className="flex items-center gap-1.5">
                  <Clock className="w-3.5 h-3.5 text-slate-500" />
                  Horários Disponíveis ({horarios.length}h selecionadas)
                </span>
                <span className="text-[11px] text-slate-500 lowercase">
                  clique para alternar
                </span>
              </label>

              <div className="flex flex-wrap gap-1.5 p-2 bg-slate-800/40 border border-slate-700/50 rounded-xl max-h-36 overflow-y-auto">
                {HORARIOS_DISPONIVEIS.map((h) => {
                  const ocupado = horariosOcupados.includes(h);
                  const selecionado = horarios.includes(h);
                  const horaFim = String(parseInt(h.split(":")[0], 10) + 1).padStart(2, "0") + ":00";

                  return (
                    <button
                      key={h}
                      type="button"
                      disabled={ocupado}
                      onClick={() => toggleHorario(h)}
                      className={`px-2.5 py-1.5 rounded-lg text-xs font-mono font-medium transition-all ${
                        selecionado
                          ? "bg-sky-500 text-slate-950 font-bold shadow-md shadow-sky-500/20"
                          : ocupado
                          ? "bg-slate-800/40 text-slate-600 line-through cursor-not-allowed border border-slate-800"
                          : "bg-slate-800 border border-slate-700/80 text-slate-300 hover:text-white hover:bg-slate-700 cursor-pointer"
                      }`}
                      title={ocupado ? "Horário indisponível" : `${h} às ${horaFim}`}
                    >
                      {h}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Linha 3: Cliente & Contato */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                  <User className="w-3.5 h-3.5 text-slate-500" />
                  Nome do Cliente / Grupo *
                </label>
                <input
                  type="text"
                  placeholder="Ex: Turma da Quarta / Carlos"
                  value={nomeCliente}
                  onChange={(e) => setNomeCliente(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-sky-500 transition-colors"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                  <Phone className="w-3.5 h-3.5 text-slate-500" />
                  WhatsApp (Opcional)
                </label>
                <input
                  type="tel"
                  placeholder="Ex: 11999998888"
                  value={whatsappCliente}
                  onChange={(e) => setWhatsappCliente(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-sky-500 transition-colors"
                />
              </div>
            </div>

            {/* Linha 4: Esporte */}
            <div>
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5">
                Esporte Praticado
              </label>
              <div className="flex flex-wrap gap-2">
                {ESPORTES.map((esp) => {
                  const ativo = esporte === esp;
                  return (
                    <button
                      key={esp}
                      type="button"
                      onClick={() => setEsporte(esp)}
                      className={`px-3 py-1.5 rounded-xl text-xs font-medium transition-all ${
                        ativo
                          ? "bg-emerald-500/20 border border-emerald-500 text-emerald-300 font-semibold"
                          : "bg-slate-800 border border-slate-700 text-slate-400 hover:text-white"
                      }`}
                    >
                      {esp}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Linha 5: Financeiro e Pagamento */}
            <div className="p-4 rounded-xl bg-slate-800/40 border border-slate-700/50 space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-xs font-bold text-white flex items-center gap-1.5">
                    <DollarSign className="w-4 h-4 text-emerald-400" />
                    Situação de Pagamento
                  </p>
                  <p className="text-[11px] text-slate-400 mt-0.5">
                    Defina se o valor foi quitado no balcão ou ficará pendente
                  </p>
                </div>

                {/* Switch Pago / Pendente */}
                <button
                  type="button"
                  onClick={() => setPago(!pago)}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
                    pago
                      ? "bg-emerald-500 text-slate-950 shadow-md shadow-emerald-500/20"
                      : "bg-amber-500/20 border border-amber-500/40 text-amber-400"
                  }`}
                >
                  {pago ? (
                    <>
                      <CheckCircle2 className="w-3.5 h-3.5" />
                      Pago Integralmente
                    </>
                  ) : (
                    <>
                      <AlertCircle className="w-3.5 h-3.5" />
                      Pendente (Pagar no Local)
                    </>
                  )}
                </button>
              </div>

              {/* Valor cobrado */}
              <div className="flex items-center justify-between pt-2 border-t border-slate-700/30 text-xs">
                <span className="text-slate-400">Valor Cobrado:</span>
                <div className="flex items-center gap-2">
                  <span className="text-slate-500">R$</span>
                  <input
                    type="number"
                    step="0.01"
                    placeholder={valorPadrao.toFixed(2)}
                    value={valorCustomizado}
                    onChange={(e) => setValorCustomizado(e.target.value)}
                    className="w-24 bg-slate-800 border border-slate-700 rounded-lg px-2 py-1 text-right text-sm text-white focus:outline-none focus:border-sky-500"
                  />
                  <span className="text-xs text-slate-400 font-mono">
                    ({formatarMoeda(valorFinal)})
                  </span>
                </div>
              </div>
            </div>

            {/* Linha 6: Observações */}
            <div>
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                <MessageSquare className="w-3.5 h-3.5 text-slate-500" />
                Observações Administrativas (Opcional)
              </label>
              <textarea
                rows={2}
                placeholder="Ex: Contato feito pelo WhatsApp da diretoria; solicitou bola extra."
                value={observacoes}
                onChange={(e) => setObservacoes(e.target.value)}
                className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-sky-500 transition-colors resize-none"
              />
            </div>

            {/* Footer Buttons */}
            <div className="flex items-center justify-end gap-3 pt-3 border-t border-slate-700/50">
              <button
                type="button"
                onClick={onFechar}
                disabled={salvando}
                className="px-4 py-2.5 rounded-xl border border-slate-700 text-slate-300 hover:text-white hover:bg-slate-800 text-sm font-medium transition-colors"
              >
                Cancelar
              </button>
              <button
                type="submit"
                id="btn-confirmar-reserva-manual"
                disabled={salvando}
                className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-sky-500 hover:bg-sky-400 text-slate-950 text-sm font-bold shadow-lg shadow-sky-500/20 active:scale-95 transition-all cursor-pointer disabled:opacity-50"
              >
                <PlusCircle className="w-4 h-4" />
                {salvando ? "Salvando..." : "Confirmar Agendamento"}
              </button>
            </div>
          </form>
        </div>
      </div>
    </>
  );
}

/**
 * ModalBloqueioHorario — Permite ao administrador bloquear quadras para manutenção ou motivos internos.
 * Possui validação estrita de prevenção de conflitos, impedindo bloquear horários que já tenham reservas confirmadas.
 */

"use client";

import { useState, useEffect, useCallback } from "react";
import {
  X,
  Wrench,
  Calendar,
  Clock,
  Layers,
  AlertTriangle,
  Lock,
  MessageSquare,
} from "lucide-react";
import { QUADRAS, HORARIOS_DISPONIVEIS } from "@/lib/quadras";
import { MOTIVOS_BLOQUEIO_SUGERIDOS } from "@/lib/adminAgenda/types";
import { formatarDataExibicao, saoConsecutivos } from "@/lib/constants";
import { useReservasService } from "@/hooks/useReservasService";
import { toast } from "sonner";

interface Props {
  aberto: boolean;
  quadraIdPadrao?: string;
  dataPadrao?: string;
  horariosPadrao?: string[];
  onFechar: () => void;
  onSucesso?: () => void;
}

export function ModalBloqueioHorario({
  aberto,
  quadraIdPadrao,
  dataPadrao,
  horariosPadrao,
  onFechar,
  onSucesso,
}: Props) {
  const { reservas, criarBloqueio } = useReservasService();

  const [quadraId, setQuadraId] = useState(quadraIdPadrao || "q1");
  const [data, setData] = useState(dataPadrao || new Date().toISOString().split("T")[0]);
  const [horarios, setHorarios] = useState<string[]>(horariosPadrao || ["08:00"]);
  const [motivo, setMotivo] = useState<string>(MOTIVOS_BLOQUEIO_SUGERIDOS[0]);
  const [motivoCustomizado, setMotivoCustomizado] = useState("");
  const [observacoes, setObservacoes] = useState("");
  const [salvando, setSalvando] = useState(false);
  const [conflitoMensagem, setConflitoMensagem] = useState<string | null>(null);

  // Sincroniza dados iniciais ao abrir o modal
  useEffect(() => {
    if (aberto) {
      if (quadraIdPadrao) setQuadraId(quadraIdPadrao);
      if (dataPadrao) setData(dataPadrao);
      if (horariosPadrao && horariosPadrao.length > 0) {
        setHorarios([...horariosPadrao].sort());
      }
      setMotivo(MOTIVOS_BLOQUEIO_SUGERIDOS[0]);
      setMotivoCustomizado("");
      setObservacoes("");
      setConflitoMensagem(null);
    }
  }, [aberto, quadraIdPadrao, dataPadrao, horariosPadrao]);

  // Fechar com Escape
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") onFechar();
    },
    [onFechar]
  );

  useEffect(() => {
    if (!aberto) return;
    document.addEventListener("keydown", handleKeyDown);
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      document.body.style.overflow = "";
    };
  }, [aberto, handleKeyDown]);

  // Verifica se há conflito prévio toda vez que quadra, data ou horários mudam
  useEffect(() => {
    if (!aberto) return;

    const conflito = reservas.find(
      (r) =>
        r.quadraId === quadraId &&
        r.data === data &&
        r.status !== "cancelada" &&
        r.horarios.some((h) => horarios.includes(h))
    );

    if (conflito) {
      if (conflito.tipoReserva === "manutencao_bloqueio") {
        setConflitoMensagem(
          `O horário já está bloqueado (${conflito.nomeCliente}).`
        );
      } else {
        setConflitoMensagem(
          `Conflito: Já existe reserva confirmada para "${conflito.nomeCliente}" (${conflito.horaInicio}–${conflito.horaFim}). Cancele ou remaneje a reserva antes de bloquear.`
        );
      }
    } else {
      setConflitoMensagem(null);
    }
  }, [aberto, quadraId, data, horarios, reservas]);

  if (!aberto) return null;

  function toggleHorario(h: string) {
    let proximo: string[];
    if (horarios.includes(h)) {
      proximo = horarios.filter((item) => item !== h);
    } else {
      proximo = [...horarios, h].sort();
    }

    if (proximo.length > 1 && !saoConsecutivos(proximo)) {
      toast.warning("Selecione horários consecutivos", {
        description: "Os horários de um mesmo bloqueio devem ser contínuos.",
      });
      return;
    }

    setHorarios(proximo);
  }

  const motivoFinal =
    motivo === "Outro motivo administrativo" && motivoCustomizado.trim()
      ? motivoCustomizado.trim()
      : motivo;

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();

    if (horarios.length === 0) {
      toast.error("Selecione ao menos um horário para aplicar o bloqueio.");
      return;
    }

    if (!motivoFinal.trim()) {
      toast.error("Informe o motivo do bloqueio.");
      return;
    }

    setSalvando(true);

    try {
      const res = await criarBloqueio({
        quadraId,
        data,
        horarios,
        motivo: motivoFinal,
        observacoes: observacoes.trim(),
      });

      if (!res.ok) {
        toast.error("Não foi possível realizar o bloqueio", {
          description: res.motivo,
        });
        return;
      }

      toast.success("Horário bloqueado com sucesso!", {
        description: `Bloqueio aplicado para ${formatarDataExibicao(data)} (${horarios.join(", ")}).`,
      });

      onSucesso?.();
      onFechar();
    } finally {
      setSalvando(false);
    }
  }

  return (
    <>
      {/* Backdrop */}
      <div
        className="fixed inset-0 z-50 bg-black/75 backdrop-blur-sm animate-fade-in"
        onClick={onFechar}
      />

      {/* Modal Container */}
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4 pointer-events-none">
        <div className="bg-slate-900 border border-slate-700/60 rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden pointer-events-auto max-h-[90vh] flex flex-col animate-scale-in">
          {/* Header */}
          <div className="flex items-center justify-between px-6 py-4 border-b border-slate-700/50 bg-slate-900 sticky top-0 z-10">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center">
                <Wrench className="w-4 h-4 text-amber-400" />
              </div>
              <div>
                <h2 className="text-base font-bold text-white leading-tight">
                  Bloquear Horário na Quadra
                </h2>
                <p className="text-xs text-slate-400">
                  Interditar horários para manutenção, limpeza ou motivos internos
                </p>
              </div>
            </div>
            <button
              onClick={onFechar}
              className="w-8 h-8 flex items-center justify-center rounded-xl bg-slate-800 border border-slate-700 text-slate-400 hover:text-white transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
            {/* Alerta de Conflito Ativo */}
            {conflitoMensagem && (
              <div className="p-3.5 rounded-xl bg-red-500/10 border border-red-500/40 text-red-300 text-xs flex items-start gap-2.5 animate-shake">
                <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                <div>
                  <p className="font-bold text-red-200">Ação Bloqueada por Conflito</p>
                  <p className="mt-0.5 leading-relaxed text-red-300/90">{conflitoMensagem}</p>
                </div>
              </div>
            )}

            {/* Linha 1: Quadra e Data */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                  <Layers className="w-3.5 h-3.5 text-slate-500" />
                  Quadra
                </label>
                <select
                  value={quadraId}
                  onChange={(e) => setQuadraId(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white focus:outline-none focus:border-amber-500 transition-colors"
                >
                  {QUADRAS.map((q) => (
                    <option key={q.id} value={q.id}>
                      Quadra {q.numero} (Poliesportiva)
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                  <Calendar className="w-3.5 h-3.5 text-slate-500" />
                  Data do Bloqueio
                </label>
                <input
                  type="date"
                  value={data}
                  onChange={(e) => setData(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white focus:outline-none focus:border-amber-500 transition-colors"
                />
              </div>
            </div>

            {/* Linha 2: Horários */}
            <div>
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center justify-between">
                <span className="flex items-center gap-1.5">
                  <Clock className="w-3.5 h-3.5 text-slate-500" />
                  Horários a Interditar ({horarios.length}h selecionadas)
                </span>
                <span className="text-[11px] text-slate-500 lowercase">
                  clique para alternar
                </span>
              </label>

              <div className="flex flex-wrap gap-1.5 p-2 bg-slate-800/40 border border-slate-700/50 rounded-xl max-h-36 overflow-y-auto">
                {HORARIOS_DISPONIVEIS.map((h) => {
                  const selecionado = horarios.includes(h);
                  return (
                    <button
                      key={h}
                      type="button"
                      onClick={() => toggleHorario(h)}
                      className={`px-2.5 py-1.5 rounded-lg text-xs font-mono font-medium transition-all ${
                        selecionado
                          ? "bg-amber-500 text-slate-950 font-bold shadow-md shadow-amber-500/20"
                          : "bg-slate-800 border border-slate-700/80 text-slate-300 hover:text-white hover:bg-slate-700 cursor-pointer"
                      }`}
                    >
                      {h}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Linha 3: Motivo */}
            <div>
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5">
                Motivo do Bloqueio
              </label>
              <select
                value={motivo}
                onChange={(e) => setMotivo(e.target.value)}
                className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white focus:outline-none focus:border-amber-500 transition-colors"
              >
                {MOTIVOS_BLOQUEIO_SUGERIDOS.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>

              {motivo === "Outro motivo administrativo" && (
                <input
                  type="text"
                  placeholder="Especifique o motivo do bloqueio..."
                  value={motivoCustomizado}
                  onChange={(e) => setMotivoCustomizado(e.target.value)}
                  className="w-full mt-2 bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-amber-500 transition-colors"
                />
              )}
            </div>

            {/* Linha 4: Observações adicionais */}
            <div>
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                <MessageSquare className="w-3.5 h-3.5 text-slate-500" />
                Detalhes ou Instruções da Equipe (Opcional)
              </label>
              <textarea
                rows={2}
                placeholder="Ex: Empresa terceirizada de manutenção chegará às 09h; chaves com o porteiro."
                value={observacoes}
                onChange={(e) => setObservacoes(e.target.value)}
                className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-amber-500 transition-colors resize-none"
              />
            </div>

            {/* Informação sobre faturamento */}
            <div className="p-3 rounded-xl bg-slate-800/40 border border-slate-700/50 flex items-center gap-2.5 text-xs text-slate-400">
              <Lock className="w-4 h-4 text-slate-500 flex-shrink-0" />
              <span>
                Horários bloqueados aparecerão como <strong>indisponíveis</strong> para os clientes no portal e <strong>não afetam os relatórios de faturamento</strong>.
              </span>
            </div>

            {/* Footer Buttons */}
            <div className="flex items-center justify-end gap-3 pt-3 border-t border-slate-700/50">
              <button
                type="button"
                onClick={onFechar}
                disabled={salvando}
                className="px-4 py-2.5 rounded-xl border border-slate-700 text-slate-300 hover:text-white hover:bg-slate-800 text-sm font-medium transition-colors"
              >
                Cancelar
              </button>
              <button
                type="submit"
                id="btn-confirmar-bloqueio"
                disabled={salvando || Boolean(conflitoMensagem)}
                className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-amber-500 hover:bg-amber-400 text-slate-950 text-sm font-bold shadow-lg shadow-amber-500/20 active:scale-95 transition-all cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <Lock className="w-4 h-4" />
                {salvando ? "Bloqueando..." : "Confirmar Bloqueio"}
              </button>
            </div>
          </form>
        </div>
      </div>
    </>
  );
}

/**
 * CalendarioMensal — Visualização panorâmica da agenda do complexo em formato de calendário mensal.
 * Permite navegação temporal (histórico passado ilimitado e até 6 meses no futuro) com lazy loading,
 * exibindo indicadores de ocupação, reservas manuais e bloqueios em cada dia.
 */

"use client";

import { useMemo } from "react";
import {
  ChevronLeft,
  ChevronRight,
  Calendar as CalendarIcon,
  ShieldCheck,
  Wrench,
  Clock,
  Sparkles,
} from "lucide-react";
import type { Reserva } from "@/store/useReservasStore";
import {
  gerarDiasCalendarioMensal,
  calcularResumoMes,
  isNavegacaoMesPermitida,
  getNomeMesExtenso,
} from "@/lib/adminAgenda/adminAgendaService";
import type { DiaCalendarioMensal } from "@/lib/adminAgenda/types";

interface Props {
  ano: number;
  mes: number;
  dataSelecionada: string;
  reservas: Reserva[];
  onMudarMes: (novoAno: number, novoMes: number) => void;
  onSelecionarDia: (data: string) => void;
  onIrParaHoje: () => void;
}

const DIAS_SEMANA_CABECALHO = ["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"];

export function CalendarioMensal({
  ano,
  mes,
  dataSelecionada,
  reservas,
  onMudarMes,
  onSelecionarDia,
  onIrParaHoje,
}: Props) {
  const hoje = useMemo(() => new Date(), []);
  const hojeIso = useMemo(() => {
    const y = hoje.getFullYear();
    const m = String(hoje.getMonth() + 1).padStart(2, "0");
    const d = String(hoje.getDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  }, [hoje]);

  const dias = useMemo(() => {
    return gerarDiasCalendarioMensal(ano, mes, reservas, hojeIso);
  }, [ano, mes, reservas, hojeIso]);

  const resumo = useMemo(() => {
    return calcularResumoMes(ano, mes, dias);
  }, [ano, mes, dias]);

  const { podeVoltar, podeAvancar } = useMemo(() => {
    return isNavegacaoMesPermitida(ano, mes, hoje);
  }, [ano, mes, hoje]);

  function voltarMes() {
    if (!podeVoltar) return;
    if (mes === 1) {
      onMudarMes(ano - 1, 12);
    } else {
      onMudarMes(ano, mes - 1);
    }
  }

  function avancarMes() {
    if (!podeAvancar) return;
    if (mes === 12) {
      onMudarMes(ano + 1, 1);
    } else {
      onMudarMes(ano, mes + 1);
    }
  }

  return (
    <div className="space-y-4">
      {/* ── Barra Superior de Navegação do Calendário ── */}
      <div className="bg-slate-900 border border-slate-700/60 rounded-2xl p-4 sm:p-5 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 shadow-xl">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center flex-shrink-0">
            <CalendarIcon className="w-5 h-5 text-emerald-400" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-white leading-tight">
              {getNomeMesExtenso(mes)} <span className="text-slate-400 font-mono">{ano}</span>
            </h2>
            <p className="text-xs text-slate-400 mt-0.5">
              Navegação de histórico e projeções da agenda completa
            </p>
          </div>
        </div>

        {/* Controles de Mês */}
        <div className="flex items-center gap-2 self-start sm:self-auto">
          <button
            type="button"
            onClick={onIrParaHoje}
            className="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 border border-slate-700 text-xs font-semibold text-slate-300 hover:text-white transition-colors"
          >
            Mês Atual
          </button>

          <div className="flex items-center rounded-xl bg-slate-800/80 border border-slate-700/80 p-0.5">
            <button
              type="button"
              id="btn-calendario-mes-anterior"
              onClick={voltarMes}
              disabled={!podeVoltar}
              title="Mês anterior (histórico)"
              className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-400 hover:text-white hover:bg-slate-700 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="w-px h-4 bg-slate-700 mx-0.5" />
            <button
              type="button"
              id="btn-calendario-proximo-mes"
              onClick={avancarMes}
              disabled={!podeAvancar}
              title={
                podeAvancar
                  ? "Próximo mês"
                  : "Limite de 6 meses no futuro atingido"
              }
              className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-400 hover:text-white hover:bg-slate-700 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* ── Cards de Métricas do Mês ── */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <div className="bg-slate-900/80 border border-slate-800 rounded-xl p-3">
          <p className="text-[11px] font-semibold text-slate-400 uppercase tracking-wider">
            Reservas do Mês
          </p>
          <p className="text-xl font-bold text-white mt-1">
            {resumo.totalReservas}
          </p>
          <p className="text-[10px] text-slate-500 mt-0.5">
            em {resumo.diasComReservas} dias com jogos
          </p>
        </div>

        <div className="bg-slate-900/80 border border-slate-800 rounded-xl p-3">
          <p className="text-[11px] font-semibold text-amber-400/90 uppercase tracking-wider flex items-center gap-1">
            <Wrench className="w-3 h-3 text-amber-400" />
            Bloqueios
          </p>
          <p className="text-xl font-bold text-amber-300 mt-1">
            {resumo.totalBloqueios}
          </p>
          <p className="text-[10px] text-slate-500 mt-0.5">
            manutenções e eventos
          </p>
        </div>

        <div className="bg-slate-900/80 border border-slate-800 rounded-xl p-3">
          <p className="text-[11px] font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-1">
            <Clock className="w-3 h-3 text-slate-500" />
            Horas Ocupadas
          </p>
          <p className="text-xl font-bold text-emerald-400 mt-1">
            {resumo.totalHorariosOcupados}h
          </p>
          <p className="text-[10px] text-slate-500 mt-0.5">
            total nas 3 quadras
          </p>
        </div>

        <div className="bg-slate-900/80 border border-slate-800 rounded-xl p-3">
          <p className="text-[11px] font-semibold text-sky-400/90 uppercase tracking-wider flex items-center gap-1">
            <Sparkles className="w-3 h-3 text-sky-400" />
            Dia Selecionado
          </p>
          <p className="text-sm font-bold text-sky-300 mt-1.5 font-mono truncate">
            {dataSelecionada}
          </p>
          <p className="text-[10px] text-slate-500 mt-0.5">
            clique em um dia abaixo
          </p>
        </div>
      </div>

      {/* ── Grid Principal do Calendário Mensal ── */}
      <div className="bg-slate-900 border border-slate-700/60 rounded-2xl overflow-hidden shadow-2xl">
        {/* Cabeçalho dos Dias da Semana */}
        <div className="grid grid-cols-7 border-b border-slate-700/50 bg-slate-800/60 text-center py-2.5">
          {DIAS_SEMANA_CABECALHO.map((diaSemana, idx) => (
            <span
              key={diaSemana}
              className={`text-xs font-bold uppercase tracking-wider ${
                idx === 0 || idx === 6 ? "text-emerald-400/80" : "text-slate-400"
              }`}
            >
              {diaSemana}
            </span>
          ))}
        </div>

        {/* Grade de Células de Dias */}
        <div className="grid grid-cols-7 divide-x divide-y divide-slate-800/70 border-b border-slate-800">
          {dias.map((d: DiaCalendarioMensal) => {
            const isSelecionado = d.data === dataSelecionada;
            const temAtividade = d.totalReservas > 0 || d.totalBloqueios > 0;

            return (
              <button
                key={d.data}
                type="button"
                onClick={() => onSelecionarDia(d.data)}
                className={`min-h-[88px] sm:min-h-[104px] p-2 flex flex-col justify-between text-left transition-all relative group cursor-pointer ${
                  !d.mesAtual
                    ? "bg-slate-950/40 text-slate-600 hover:bg-slate-900/50"
                    : isSelecionado
                    ? "bg-emerald-500/10 ring-2 ring-emerald-500 ring-inset z-10"
                    : d.isHoje
                    ? "bg-slate-800/40 hover:bg-slate-800/80"
                    : "bg-slate-900/90 hover:bg-slate-800/50 text-slate-300"
                }`}
              >
                {/* Linha superior: Número do dia + badges */}
                <div className="flex items-start justify-between w-full">
                  <span
                    className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold transition-all ${
                      d.isHoje
                        ? "bg-emerald-500 text-slate-950 shadow-md shadow-emerald-500/30"
                        : isSelecionado
                        ? "bg-emerald-500/20 text-emerald-400 font-black"
                        : d.mesAtual
                        ? "text-slate-200 group-hover:text-white"
                        : "text-slate-600"
                    }`}
                  >
                    {d.diaNumero}
                  </span>

                  {d.isHoje && (
                    <span className="text-[9px] uppercase font-bold text-emerald-400 bg-emerald-500/10 px-1.5 py-0.5 rounded-full border border-emerald-500/20 hidden sm:inline-block">
                      Hoje
                    </span>
                  )}
                </div>

                {/* Linha intermediária / inferior: Indicadores de Ocupação */}
                <div className="mt-1 space-y-1 w-full">
                  {d.totalReservas > 0 && (
                    <div className="flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-emerald-500/15 border border-emerald-500/30 text-emerald-300 text-[10px] font-semibold truncate">
                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 flex-shrink-0" />
                      <span className="truncate">
                        {d.totalReservas} {d.totalReservas === 1 ? "reserva" : "reservas"}
                      </span>
                    </div>
                  )}

                  {d.totalBloqueios > 0 && (
                    <div className="flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-amber-500/15 border border-amber-500/30 text-amber-300 text-[10px] font-semibold truncate">
                      <Wrench className="w-2.5 h-2.5 text-amber-400 flex-shrink-0" />
                      <span className="truncate">
                        {d.totalBloqueios} {d.totalBloqueios === 1 ? "bloqueio" : "bloqueios"}
                      </span>
                    </div>
                  )}

                  {!temAtividade && d.mesAtual && (
                    <p className="text-[10px] text-slate-600 italic px-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      Livre
                    </p>
                  )}
                </div>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

/**
 * VisaoDiaGrade — Visualização simplificada da agenda diária por quadras.
 * Inspirada na experiência do usuário final para facilitar o panorama geral do dia,
 * permitindo ao administrador identificar horários livres, reservas manuais e bloqueios.
 */

"use client";

import { useState } from "react";
import {
  ChevronLeft,
  ChevronRight,
  PlusCircle,
  Lock,
  Unlock,
  CheckCircle2,
  AlertCircle,
  ShieldCheck,
  User,
  Wrench,
  GraduationCap,
  UsersRound,
  Layers,
  Sparkles,
  Calendar,
} from "lucide-react";
import { QUADRAS, type Quadra } from "@/lib/quadras";
import { formatarDataExibicao, formatarMoeda } from "@/lib/constants";
import type { Reserva } from "@/store/useReservasStore";
import { montarSlotsQuadraDia } from "@/lib/adminAgenda/adminAgendaService";
import type { SlotAgendaAdmin } from "@/lib/adminAgenda/types";
import { useReservasService } from "@/hooks/useReservasService";
import { toast } from "sonner";

interface Props {
  data: string;
  onMudarData: (novaData: string) => void;
  onAbrirReservaManual: (quadraId?: string, horario?: string) => void;
  onAbrirBloqueio: (quadraId?: string, horario?: string) => void;
  onVerDetalhesReserva: (reserva: Reserva) => void;
}

export function VisaoDiaGrade({
  data,
  onMudarData,
  onAbrirReservaManual,
  onAbrirBloqueio,
  onVerDetalhesReserva,
}: Props) {
  const { reservas, removerBloqueio } = useReservasService();
  const [quadraFiltro, setQuadraFiltro] = useState<string>("todas");

  // Navegação entre dias (anterior e próximo)
  function navDia(delta: number) {
    const [y, m, d] = data.split("-").map(Number);
    const atual = new Date(y, m - 1, d);
    atual.setDate(atual.getDate() + delta);
    const novoAno = atual.getFullYear();
    const novoMes = String(atual.getMonth() + 1).padStart(2, "0");
    const novoDia = String(atual.getDate()).padStart(2, "0");
    onMudarData(`${novoAno}-${novoMes}-${novoDia}`);
  }

  const quadrasExibidas =
    quadraFiltro === "todas"
      ? QUADRAS
      : QUADRAS.filter((q) => q.id === quadraFiltro);

  async function handleDesbloquear(bloqueioId: string, e: React.MouseEvent) {
    e.stopPropagation();
    const confirmou = window.confirm(
      "Deseja realmente remover este bloqueio e liberar o horário?"
    );
    if (!confirmou) return;

    const ok = await removerBloqueio(bloqueioId);
    if (ok) {
      toast.success("Horário desbloqueado com sucesso!");
    } else {
      toast.error("Não foi possível desbloquear o horário.");
    }
  }

  return (
    <div className="space-y-6">
      {/* ── Topbar de Navegação do Dia e Ações Rápidas ── */}
      <div className="bg-slate-900 border border-slate-700/60 rounded-2xl p-4 sm:p-5 flex flex-col md:flex-row md:items-center md:justify-between gap-4 shadow-xl">
        <div className="flex items-center gap-3">
          <div className="flex items-center rounded-xl bg-slate-800 border border-slate-700 p-0.5">
            <button
              type="button"
              id="btn-grade-dia-anterior"
              onClick={() => navDia(-1)}
              title="Dia anterior"
              className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-400 hover:text-white hover:bg-slate-700 transition-colors"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="w-px h-4 bg-slate-700 mx-0.5" />
            <button
              type="button"
              id="btn-grade-proximo-dia"
              onClick={() => navDia(1)}
              title="Próximo dia"
              className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-400 hover:text-white hover:bg-slate-700 transition-colors"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>

          <div>
            <h2 className="text-lg font-bold text-white leading-tight capitalize">
              {formatarDataExibicao(data, {
                weekday: "long",
                day: "numeric",
                month: "long",
                year: "numeric",
              })}
            </h2>
            <p className="text-xs text-slate-400 font-mono mt-0.5">
              Grade diária completa · Visão detalhada por quadra
            </p>
          </div>
        </div>

        {/* Botões de Ação do Admin */}
        <div className="flex flex-wrap items-center gap-2.5">
          <button
            type="button"
            id="btn-topo-bloquear-horario"
            onClick={() => onAbrirBloqueio()}
            className="flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/30 text-amber-300 text-xs font-semibold active:scale-95 transition-all cursor-pointer"
          >
            <Lock className="w-3.5 h-3.5 text-amber-400" />
            Bloquear Horário
          </button>

          <button
            type="button"
            id="btn-topo-reserva-manual"
            onClick={() => onAbrirReservaManual()}
            className="flex items-center gap-1.5 px-4 py-2 rounded-xl bg-sky-500 hover:bg-sky-400 text-slate-950 text-xs font-bold shadow-md shadow-sky-500/20 active:scale-95 transition-all cursor-pointer"
          >
            <PlusCircle className="w-3.5 h-3.5" />
            Nova Reserva Manual
          </button>
        </div>
      </div>

      {/* ── Filtro de Quadras ── */}
      <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
        <button
          type="button"
          onClick={() => setQuadraFiltro("todas")}
          className={`px-3.5 py-1.5 rounded-xl text-xs font-semibold transition-all cursor-pointer ${
            quadraFiltro === "todas"
              ? "bg-emerald-500 text-slate-950 shadow-md shadow-emerald-500/20"
              : "bg-slate-800 border border-slate-700 text-slate-300 hover:text-white"
          }`}
        >
          Todas as Quadras (3)
        </button>
        {QUADRAS.map((q) => (
          <button
            key={q.id}
            type="button"
            onClick={() => setQuadraFiltro(q.id)}
            className={`px-3.5 py-1.5 rounded-xl text-xs font-semibold transition-all cursor-pointer ${
              quadraFiltro === q.id
                ? "bg-emerald-500 text-slate-950 shadow-md shadow-emerald-500/20"
                : "bg-slate-800 border border-slate-700 text-slate-300 hover:text-white"
            }`}
          >
            Quadra {q.numero}
          </button>
        ))}
      </div>

      {/* ── Seção de Cada Quadra ── */}
      <div className="space-y-6">
        {quadrasExibidas.map((quadra: Quadra) => {
          const slots = montarSlotsQuadraDia(quadra.id, data, reservas);
          const ocupadosCount = slots.filter((s) => s.tipo !== "disponivel").length;

          return (
            <div
              key={quadra.id}
              className="bg-slate-900 border border-slate-700/60 rounded-2xl overflow-hidden shadow-xl"
            >
              {/* Header da Quadra */}
              <div className="px-5 py-3.5 border-b border-slate-700/50 bg-slate-800/50 flex items-center justify-between">
                <div className="flex items-center gap-2.5">
                  <div className="w-8 h-8 rounded-lg bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center font-bold text-emerald-400 text-xs">
                    Q{quadra.numero}
                  </div>
                  <div>
                    <h3 className="font-bold text-white text-sm">
                      Quadra {quadra.numero}
                    </h3>
                    <p className="text-[11px] text-slate-400">
                      {quadra.descricao} · {ocupadosCount} de {slots.length} horários ocupados
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={() => onAbrirBloqueio(quadra.id)}
                    className="text-xs text-amber-400/90 hover:text-amber-300 flex items-center gap-1 font-medium px-2 py-1 rounded-lg hover:bg-amber-500/10 transition-colors"
                  >
                    <Lock className="w-3 h-3" />
                    <span className="hidden sm:inline">Bloquear Horário</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => onAbrirReservaManual(quadra.id)}
                    className="text-xs text-sky-400/90 hover:text-sky-300 flex items-center gap-1 font-medium px-2 py-1 rounded-lg hover:bg-sky-500/10 transition-colors"
                  >
                    <PlusCircle className="w-3 h-3" />
                    <span className="hidden sm:inline">Agendar</span>
                  </button>
                </div>
              </div>

              {/* Grid de Horários da Quadra */}
              <div className="p-4 sm:p-5">
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-7 gap-3">
                  {slots.map((slot: SlotAgendaAdmin) => {
                    // 1. Slot Disponível (Livre)
                    if (slot.tipo === "disponivel") {
                      return (
                        <div
                          key={slot.horario}
                          className="flex flex-col justify-between p-3 rounded-xl border border-slate-700/70 bg-slate-800/30 hover:border-emerald-500/60 hover:bg-slate-800/80 transition-all group select-none min-h-[96px]"
                        >
                          <div>
                            <div className="flex items-center justify-between">
                              <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-400">
                                Livre
                              </span>
                              <span className="text-[10px] text-slate-500 font-mono">
                                {slot.horario}
                              </span>
                            </div>
                            <p className="text-sm font-bold text-white mt-1 font-mono">
                              {slot.horario} – {slot.horaFim}
                            </p>
                          </div>

                          <div className="flex items-center justify-between gap-1 pt-2 border-t border-slate-700/30 mt-2 opacity-80 group-hover:opacity-100 transition-opacity">
                            <button
                              type="button"
                              onClick={() => onAbrirReservaManual(quadra.id, slot.horario)}
                              title="Criar Reserva Manual neste horário"
                              className="text-[11px] font-bold text-sky-400 hover:text-sky-300 flex items-center gap-0.5 hover:underline"
                            >
                              + Reserva
                            </button>
                            <button
                              type="button"
                              onClick={() => onAbrirBloqueio(quadra.id, slot.horario)}
                              title="Bloquear este horário para manutenção"
                              className="text-[11px] font-medium text-amber-400/80 hover:text-amber-300 flex items-center gap-0.5 hover:underline"
                            >
                              <Lock className="w-2.5 h-2.5" />
                              Bloquear
                            </button>
                          </div>
                        </div>
                      );
                    }

                    // 2. Slot com Bloqueio de Manutenção
                    if (slot.tipo === "manutencao_bloqueio") {
                      return (
                        <div
                          key={slot.horario}
                          className="flex flex-col justify-between p-3 rounded-xl border border-amber-500/40 bg-amber-500/10 transition-all select-none min-h-[96px] group relative overflow-hidden"
                        >
                          <div>
                            <div className="flex items-center justify-between">
                              <span className="text-[10px] font-bold uppercase tracking-wider text-amber-300 flex items-center gap-1">
                                <Wrench className="w-3 h-3 text-amber-400" />
                                Bloqueio
                              </span>
                              <span className="text-[10px] text-amber-400/80 font-mono">
                                {slot.horario}
                              </span>
                            </div>
                            <p className="text-sm font-bold text-amber-100 mt-1 font-mono">
                              {slot.horario} – {slot.horaFim}
                            </p>
                            <p className="text-[11px] text-amber-300/90 mt-1 truncate font-medium">
                              {slot.motivoBloqueio}
                            </p>
                          </div>

                          <div className="pt-2 border-t border-amber-500/20 mt-2 flex items-center justify-between">
                            <span className="text-[10px] text-amber-400/70 italic">
                              Interditado
                            </span>
                            {slot.reserva && (
                              <button
                                type="button"
                                onClick={(e) => handleDesbloquear(slot.reserva!.id, e)}
                                title="Remover este bloqueio"
                                className="text-[11px] text-amber-300 hover:text-white font-bold flex items-center gap-1 bg-amber-500/20 px-2 py-0.5 rounded hover:bg-amber-500/40 transition-colors"
                              >
                                <Unlock className="w-3 h-3" />
                                Liberar
                              </button>
                            )}
                          </div>
                        </div>
                      );
                    }

                    // 3. Slot com Reserva Manual do Admin (Destaque Visual Azul)
                    if (slot.tipo === "admin_manual") {
                      return (
                        <button
                          key={slot.horario}
                          type="button"
                          onClick={() => slot.reserva && onVerDetalhesReserva(slot.reserva)}
                          className="flex flex-col justify-between p-3 rounded-xl border border-sky-500/40 bg-sky-500/15 hover:bg-sky-500/25 transition-all text-left select-none min-h-[96px] group cursor-pointer ring-1 ring-sky-500/20 shadow-md shadow-sky-950/40"
                        >
                          <div>
                            <div className="flex items-center justify-between">
                              <span className="text-[10px] font-bold uppercase tracking-wider text-sky-300 flex items-center gap-1">
                                <ShieldCheck className="w-3 h-3 text-sky-400" />
                                Reserva Admin
                              </span>
                              <span className="text-[10px] text-sky-300/80 font-mono">
                                {slot.horario}
                              </span>
                            </div>
                            <p className="text-sm font-bold text-sky-100 mt-1 font-mono">
                              {slot.horario} – {slot.horaFim}
                            </p>
                            <p className="text-xs font-semibold text-white mt-1 truncate">
                              {slot.nomeExibicao}
                            </p>
                          </div>

                          <div className="pt-2 border-t border-sky-500/20 mt-2 flex items-center justify-between w-full">
                            <span
                              className={`text-[10px] font-bold px-1.5 py-0.2 rounded ${
                                slot.pago
                                  ? "bg-emerald-500/30 text-emerald-300"
                                  : "bg-amber-500/30 text-amber-300"
                              }`}
                            >
                              {slot.pago ? "✓ Pago" : "Pendente"}
                            </span>
                            <span className="text-[10px] text-sky-400 font-medium group-hover:translate-x-0.5 transition-transform">
                              Detalhes →
                            </span>
                          </div>
                        </button>
                      );
                    }

                    // 4. Slot com Reserva de Escolinha ou Grupo
                    if (slot.tipo === "escolinha" || slot.tipo === "grupo") {
                      const ehEscolinha = slot.tipo === "escolinha";
                      return (
                        <button
                          key={slot.horario}
                          type="button"
                          onClick={() => slot.reserva && onVerDetalhesReserva(slot.reserva)}
                          className="flex flex-col justify-between p-3 rounded-xl border border-violet-500/40 bg-violet-500/15 hover:bg-violet-500/25 transition-all text-left select-none min-h-[96px] group cursor-pointer"
                        >
                          <div>
                            <div className="flex items-center justify-between">
                              <span className="text-[10px] font-bold uppercase tracking-wider text-violet-300 flex items-center gap-1">
                                {ehEscolinha ? (
                                  <>
                                    <GraduationCap className="w-3 h-3 text-violet-400" />
                                    Escolinha
                                  </>
                                ) : (
                                  <>
                                    <UsersRound className="w-3 h-3 text-violet-400" />
                                    Grupo
                                  </>
                                )}
                              </span>
                              <span className="text-[10px] text-violet-400/80 font-mono">
                                {slot.horario}
                              </span>
                            </div>
                            <p className="text-sm font-bold text-violet-100 mt-1 font-mono">
                              {slot.horario} – {slot.horaFim}
                            </p>
                            <p className="text-xs font-semibold text-white mt-1 truncate">
                              {slot.nomeExibicao}
                            </p>
                          </div>

                          <div className="pt-2 border-t border-violet-500/20 mt-2 flex items-center justify-between w-full">
                            <span className="text-[10px] text-violet-300 font-medium">
                              Recorrente
                            </span>
                            <span className="text-[10px] text-violet-400 group-hover:translate-x-0.5 transition-transform">
                              Ver →
                            </span>
                          </div>
                        </button>
                      );
                    }

                    // 5. Slot com Reserva Online de Cliente (Comum)
                    return (
                      <button
                        key={slot.horario}
                        type="button"
                        onClick={() => slot.reserva && onVerDetalhesReserva(slot.reserva)}
                        className="flex flex-col justify-between p-3 rounded-xl border border-emerald-500/40 bg-emerald-500/10 hover:bg-emerald-500/20 transition-all text-left select-none min-h-[96px] group cursor-pointer"
                      >
                        <div>
                          <div className="flex items-center justify-between">
                            <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-400 flex items-center gap-1">
                              <User className="w-3 h-3" />
                              Cliente Online
                            </span>
                            <span className="text-[10px] text-emerald-400/80 font-mono">
                              {slot.horario}
                            </span>
                          </div>
                          <p className="text-sm font-bold text-emerald-100 mt-1 font-mono">
                            {slot.horario} – {slot.horaFim}
                          </p>
                          <p className="text-xs font-semibold text-white mt-1 truncate">
                            {slot.nomeExibicao}
                          </p>
                        </div>

                        <div className="pt-2 border-t border-emerald-500/20 mt-2 flex items-center justify-between w-full">
                          <span
                            className={`text-[10px] font-bold px-1.5 py-0.2 rounded ${
                              slot.pago
                                ? "bg-emerald-500/30 text-emerald-300"
                                : "bg-amber-500/30 text-amber-300"
                            }`}
                          >
                            {slot.pago ? "✓ Pago" : "Pendente"}
                          </span>
                          <span className="text-[10px] text-emerald-400 group-hover:translate-x-0.5 transition-transform">
                            Detalhes →
                          </span>
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

