/**
 * BarraNavegacaoDia — Barra de navegação unificada de data para a Grade do Dia e a Timeline (Gantt).
 * Combina navegação incremental por setas (anterior/próximo) e seleção direta no calendário nativo.
 */

"use client";

import React from "react";
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon } from "lucide-react";
import { formatarDataExibicao } from "@/lib/constants";

interface Props {
  data: string;
  onMudarData: (novaData: string) => void;
  subtitulo?: string;
  children?: React.ReactNode;
}

export function BarraNavegacaoDia({
  data,
  onMudarData,
  subtitulo,
  children,
}: Props) {
  function hojeLocal(): string {
    const d = new Date();
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    return `${y}-${m}-${dd}`;
  }

  function navDia(delta: number) {
    const [y, m, d] = data.split("-").map(Number);
    const atual = new Date(y, m - 1, d);
    atual.setDate(atual.getDate() + delta);
    const novoAno = atual.getFullYear();
    const novoMes = String(atual.getMonth() + 1).padStart(2, "0");
    const novoDia = String(atual.getDate()).padStart(2, "0");
    onMudarData(`${novoAno}-${novoMes}-${novoDia}`);
  }

  const isHoje = data === hojeLocal();

  return (
    <div className="bg-slate-900 border border-slate-700/60 rounded-2xl p-4 sm:p-5 flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 shadow-xl">
      <div className="flex flex-wrap items-center gap-3">
        {/* Bloco Unificado: Seta Anterior + Seletor de Data + Seta Próximo */}
        <div className="flex items-center rounded-xl bg-slate-800 border border-slate-700 p-1 gap-1 shadow-inner">
          <button
            type="button"
            id="btn-agenda-dia-anterior"
            onClick={() => navDia(-1)}
            title="Dia anterior"
            className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-300 hover:text-white hover:bg-slate-700 transition-colors cursor-pointer"
          >
            <ChevronLeft className="w-4 h-4" />
          </button>

          {/* Input de Data Direto estilizado */}
          <div className="relative flex items-center">
            <input
              type="date"
              id="input-agenda-data"
              value={data}
              onChange={(e) => {
                if (e.target.value) {
                  onMudarData(e.target.value);
                }
              }}
              title="Escolher data diretamente no calendário"
              className="bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1 text-xs text-white font-mono focus:outline-none focus:border-emerald-500 cursor-pointer hover:border-slate-600 transition-colors"
            />
          </div>

          <button
            type="button"
            id="btn-agenda-proximo-dia"
            onClick={() => navDia(1)}
            title="Próximo dia"
            className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-300 hover:text-white hover:bg-slate-700 transition-colors cursor-pointer"
          >
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>

        {/* Botão de Atalho "Hoje" */}
        {!isHoje && (
          <button
            type="button"
            onClick={() => onMudarData(hojeLocal())}
            title="Voltar para a data de hoje"
            className="px-3 py-1.5 rounded-xl bg-emerald-500/10 hover:bg-emerald-500/20 border border-emerald-500/30 text-emerald-300 text-xs font-semibold transition-all cursor-pointer shadow-sm active:scale-95"
          >
            Hoje
          </button>
        )}

        {/* Informação Textual da Data */}
        <div>
          <h2 className="text-base sm:text-lg font-bold text-white leading-tight capitalize">
            {formatarDataExibicao(data, {
              weekday: "long",
              day: "numeric",
              month: "long",
              year: "numeric",
            })}
          </h2>
          {subtitulo && (
            <p className="text-xs text-slate-400 font-mono mt-0.5">
              {subtitulo}
            </p>
          )}
        </div>
      </div>

      {/* Conteúdo à Direita (Botões de Ação ou Legenda) */}
      {children && (
        <div className="flex flex-wrap items-center gap-2.5">
          {children}
        </div>
      )}
    </div>
  );
}

