    {slots.map((slot: SlotAgendaAdmin) => {
      // 1. Slot Disponível
      if (slot.tipo === "disponivel") {
        return (
          <div
            key={slot.horario}
            className="flex flex-col justify-between p-3.5 rounded-xl border border-slate-700/70 bg-slate-800/30 hover:border-emerald-500/60 hover:bg-slate-800/80 transition-all group select-none min-h-[110px]"
