                + Reserva
              </button>
              <button
                type="button"
                onClick={() => onAbrirBloqueio(quadra.id, slot.horario)}
                title="Bloquear este horário para manutenção"
                className="text-[11px] font-medium text-amber-400/80 hover:text-amber-300 flex items-center gap-0.5 hover:underline"
              >
                <Lock className="w-2.5 h-2.5" />
                Bloquear
              </button>
            </div>
          </div>
        );
      }

      // 2. Slot com Bloqueio de Manutenção
      if (slot.tipo === "manutencao_bloqueio") {
        return (
          <div
            key={slot.horario}
            className="flex flex-col justify-between p-3 rounded-xl border border-amber-500/40 bg-amber-500/10 transition-all select-none min-h-[96px] group relative overflow-hidden"
          >
            <div>
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-bold uppercase tracking-wider text-amber-300 flex items-center gap-1">
                  <Wrench className="w-3 h-3 text-amber-400" />
                  Bloqueio
                </span>
                <span className="text-[10px] text-amber-400/80 font-mono">
                  {slot.horario}
                </span>
              </div>
              <p className="text-sm font-bold text-amber-100 mt-1 font-mono">
                {slot.horario} – {slot.horaFim}
              </p>
              <p className="text-[11px] text-amber-300/90 mt-1 truncate font-medium">
                {slot.motivoBloqueio}
              </p>
            </div>

            <div className="pt-2 border-t border-amber-500/20 mt-2 flex items-center justify-between">
              <span className="text-[10px] text-amber-400/70 italic">
                Interditado
              </span>
              {slot.reserva && (
                <button
                  type="button"
                  onClick={(e) => handleDesbloquear(slot.reserva!.id, e)}
                  title="Remover este bloqueio"
                  className="text-[11px] text-amber-300 hover:text-white font-bold flex items-center gap-1 bg-amber-500/20 px-2 py-0.5 rounded hover:bg-amber-500/40 transition-colors"
                >
                  <Unlock className="w-3 h-3" />
                  Liberar
                </button>
              )}
            </div>
          </div>
        );
      }

      // 3. Slot com Reserva Manual do Admin (Destaque Visual Azul)
      if (slot.tipo === "admin_manual") {
        return (
          <button
            key={slot.horario}
            type="button"
            onClick={() => slot.reserva && onVerDetalhesReserva(slot.reserva)}
            className="flex flex-col justify-between p-3 rounded-xl border border-sky-500/40 bg-sky-500/15 hover:bg-sky-500/25 transition-all text-left select-none min-h-[96px] group cursor-pointer ring-1 ring-sky-500/20 shadow-md shadow-sky-950/40"
          >
            <div>
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-bold uppercase tracking-wider text-sky-300 flex items-center gap-1">
                  <ShieldCheck className="w-3 h-3 text-sky-400" />
                  Reserva Admin
                </span>
                <span className="text-[10px] text-sky-300/80 font-mono">
                  {slot.horario}
                </span>
              </div>
              <p className="text-sm font-bold text-sky-100 mt-1 font-mono">
                {slot.horario} – {slot.horaFim}
              </p>
              <p className="text-xs font-semibold text-white mt-1 truncate">
                {slot.nomeExibicao}
              </p>
            </div>

            <div className="pt-2 border-t border-sky-500/20 mt-2 flex items-center justify-between w-full">
              <span
                className={`text-[10px] font-bold px-1.5 py-0.2 rounded ${
                  slot.pago
                    ? "bg-emerald-500/30 text-emerald-300"
                    : "bg-amber-500/30 text-amber-300"
                }`}
              >
                {slot.pago ? "✓ Pago" : "Pendente"}
              </span>
              <span className="text-[10px] text-sky-400 font-medium group-hover:translate-x-0.5 transition-transform">
                Detalhes →
              </span>
            </div>
          </button>
        );
      }

      // 4. Slot com Reserva de Escolinha ou Grupo
      if (slot.tipo === "escolinha" || slot.tipo === "grupo") {
        const ehEscolinha = slot.tipo === "escolinha";
        return (
          <button
            key={slot.horario}
            type="button"
            onClick={() => slot.reserva && onVerDetalhesReserva(slot.reserva)}
            className="flex flex-col justify-between p-3 rounded-xl border border-violet-500/40 bg-violet-500/15 hover:bg-violet-500/25 transition-all text-left select-none min-h-[96px] group cursor-pointer"
          >
            <div>
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-bold uppercase tracking-wider text-violet-300 flex items-center gap-1">
                  {ehEscolinha ? (
                    <>
                      <GraduationCap className="w-3 h-3 text-violet-400" />
                      Escolinha
                    </>
                  ) : (
                    <>
                      <UsersRound className="w-3 h-3 text-violet-400" />
                      Grupo
                    </>
                  )}
                </span>
                <span className="text-[10px] text-violet-400/80 font-mono">
                  {slot.horario}
                </span>
              </div>
              <p className="text-sm font-bold text-violet-100 mt-1 font-mono">
                {slot.horario} – {slot.horaFim}
              </p>
              <p className="text-xs font-semibold text-white mt-1 truncate">
                {slot.nomeExibicao}
              </p>
            </div>

            <div className="pt-2 border-t border-violet-500/20 mt-2 flex items-center justify-between w-full">
              <span className="text-[10px] text-violet-300 font-medium">
                Recorrente
              </span>
              <span className="text-[10px] text-violet-400 group-hover:translate-x-0.5 transition-transform">
                Ver →
              </span>
            </div>
          </button>
        );
      }

      // 5. Slot com Reserva Online de Cliente (Comum)
      return (
        <button
          key={slot.horario}
          type="button"
          onClick={() => slot.reserva && onVerDetalhesReserva(slot.reserva)}
          className="flex flex-col justify-between p-3 rounded-xl border border-emerald-500/40 bg-emerald-500/10 hover:bg-emerald-500/20 transition-all text-left select-none min-h-[96px] group cursor-pointer"
        >
          <div>
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-400 flex items-center gap-1">
                <User className="w-3 h-3" />
                Cliente Online
              </span>
              <span className="text-[10px] text-emerald-400/80 font-mono">
                {slot.horario}
              </span>
            </div>
            <p className="text-sm font-bold text-emerald-100 mt-1 font-mono">
              {slot.horario} – {slot.horaFim}
            </p>
            <p className="text-xs font-semibold text-white mt-1 truncate">
              {slot.nomeExibicao}
            </p>
          </div>

          <div className="pt-2 border-t border-emerald-500/20 mt-2 flex items-center justify-between w-full">
            <span
              className={`text-[10px] font-bold px-1.5 py-0.2 rounded ${
                slot.pago
                  ? "bg-emerald-500/30 text-emerald-300"
                  : "bg-amber-500/30 text-amber-300"
              }`}
            >
              {slot.pago ? "✓ Pago" : "Pendente"}
            </span>
            <span className="text-[10px] text-emerald-400 group-hover:translate-x-0.5 transition-transform">
              Detalhes →
            </span>
          </div>
        </button>
      );
    })}
  </div>
</div>

